mapper.insert:
/* 관리자 (코드관리:그룹) 저장 쿼리 (insertGroupCode)*/
INSERT INTO OCUOC_CCGRP_M
( CD_GROUP
, CD_GROUP_NM
, LAST_CHNG_EMPNO
, LAST_CHNG_DTTM
, FRST_REG_EMPNO
, FRST_REG_DTTM
)
VALUES (
		 #{groupCd}
	   , #{groupNm}
	   , #{userId}
	   , TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISS')
	   , #{userId}
	   , TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISS')
	   )

/* 관리자 (코드관리:상세) 저장 쿼리 (insertGroupDetail)*/
INSERT INTO OCUOC_CCDTL_L
( CD_GROUP
, CD_VAL
, CD_NM
, CD_DESC
, LNUP_SER
, UZ_YN
, VLD_STDD
, VLD_ENDT
, LAST_CHNG_EMPNO
, LAST_CHNG_DTTM
, FRST_REG_EMPNO
, FRST_REG_DTTM
)
VALUES (
		 #{groupCd}
	   , #{cdVal}
	   , #{cdNm}
	   , #{cdDesc}
	   , #{lnupSer}
	   , #{useYn}
	   , TO_DATE('20261101', 'YYYY-MM-DD')
	   , TO_DATE('99991231', 'YYYY-MM-DD'),
	   , TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISS')
	   , #{userId}
	   , TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISS')
	   , #{userId}
	   , TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24MISS')
	   )

mapper.delete:
/* 관리자 (코드관리:그룹삭제시 상세까직) 삭제 쿼리 (deleteCodeDetailByGroup)*/
DELETE
FROM OCUOC_CCDTL_L
WHERE CD_GROUP = #{cdGroup}

/* 관리자 (코드관리:그룹) 삭제 쿼리 (deleteGroupCode)*/
DELETE
FROM OCUOC_CCGRP_M
WHERE CD_GROUP = #{cdGroup}

/* 관리자 (코드관리:단일상세) 삭제 쿼리 (deleteCodeDetail)*/
DELETE
FROM OCUOC_CCDTL_L
WHERE CD_GROUP = #{cdGroup}
AND CD_VAL = #{cdVal}

mapper.select:
/* 관리자 (코드관리:그룹) 총카운토 조회 쿼리 (groupCnt)*/
SELECT count(*)
FROM OCUOC_CCGRP_M
WHERE 1=1
  AND CD_GROUP = #{cdGroup}
